export function price(amount: number, qty: number): number {
  return Math.round(amount * qty * 100) / 100;
}

export function discount(amount: number): number {
  return Math.round(amount * 90) / 100;
}

A.checkout.ts:
import { price, discount } from './pricing';

export function checkout(cart: Array<{ amount: number; qty: number }>): number {
  let total = 0;
  for (const line of cart) {
    total += price(line.amount, line.qty);
  }
  return discount(total);
}

